INSERT INTO elections (year, label) VALUES
  (2014, '2014 年'),
  (2018, '2018 年'),
  (2022, '2022 年');
INSERT INTO counties (id, name, sort_order) VALUES
  ('taipei', '臺北市', 1),
  ('new-taipei', '新北市', 2),
  ('taoyuan', '桃園市', 3),
  ('taichung', '臺中市', 4),
  ('tainan', '臺南市', 5),
  ('kaohsiung', '高雄市', 6);
INSERT INTO candidates (id, election_year, county_id, name, party, vision, source_reference) VALUES
  (1, 2014, 'taipei', '柯文哲', '無黨籍', '以《台北公民憲章》推動開放政府、全民參與。', '2014/01臺北市市長.pdf（第1頁，候選人7號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/9d2614e7-1c24-4cc4-bd9d-b30c19823d5b.pdf'),
  (2, 2014, 'new-taipei', '朱立倫', '中國國民黨', '延續在地就學、就養、就業、樂活，打造進步宜居的新北市。', '2014/02新北市市長.pdf（第1頁，候選人2號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/9d2614e7-1c24-4cc4-bd9d-b30c19823d5b.pdf'),
  (3, 2014, 'taoyuan', '鄭文燦', '民主進步黨', '提出「新桃園、新選擇」，推動升格後的城市轉型。', '2014/03桃園市市長.pdf（第1頁，候選人1號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/9d2614e7-1c24-4cc4-bd9d-b30c19823d5b.pdf'),
  (4, 2014, 'taichung', '林佳龍', '民主進步黨', '促進山、海、屯、市區均衡發展，打造宜居生活首都。', '2014/04臺中市市長.pdf（第1至2頁，候選人2號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/9d2614e7-1c24-4cc4-bd9d-b30c19823d5b.pdf'),
  (5, 2014, 'tainan', '賴清德', '民主進步黨', '清廉勤政、傳承創新，建設文化首都、低碳城市、科技新城、觀光樂園與宜居臺南。', '2014/05臺南市市長.pdf（第1頁，候選人1號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/9d2614e7-1c24-4cc4-bd9d-b30c19823d5b.pdf'),
  (6, 2014, 'kaohsiung', '陳菊', '民主進步黨', '重建城市安全與市民信心，打造安全、繁榮、宜居高雄。', '2014/06高雄市市長.pdf（第1頁，候選人2號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/9d2614e7-1c24-4cc4-bd9d-b30c19823d5b.pdf'),
  (7, 2018, 'taipei', '柯文哲', '無黨籍', '延續開放政府、全民參與、公開透明、務實對話。', '2018/臺北市市長.pdf（第1頁，候選人4號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/7ec2d4d3-7807-4798-a2aa-9a5a3eb5033d.pdf'),
  (8, 2018, 'new-taipei', '侯友宜', '中國國民黨', '讓新北市民安居樂業、看見未來並建立城市光榮感。', '2018/新北市市長.pdf（第1頁，候選人2號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/7ec2d4d3-7807-4798-a2aa-9a5a3eb5033d.pdf'),
  (9, 2018, 'taoyuan', '鄭文燦', '民主進步黨', '以航空城、軌道與亞洲矽谷帶動城市升級。', '2018/桃園市市長.pdf（第1頁，候選人5號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/7ec2d4d3-7807-4798-a2aa-9a5a3eb5033d.pdf'),
  (10, 2018, 'taichung', '盧秀燕', '中國國民黨', '以陽光、空氣、水與城市競爭力為核心，提出臺中PLUS+。', '2018/臺中市市長.pdf（第1頁，候選人3號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/7ec2d4d3-7807-4798-a2aa-9a5a3eb5033d.pdf'),
  (11, 2018, 'tainan', '黃偉哲', '民主進步黨', '以做實事面對市政，團結市民、整合願景，帶領臺南前進。', '2018/臺南市市長.pdf（第1頁，候選人1號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/7ec2d4d3-7807-4798-a2aa-9a5a3eb5033d.pdf'),
  (12, 2018, 'kaohsiung', '韓國瑜', '中國國民黨', '以十大支票推動教育、招商、產業、交通、青年、照顧與環境治理。', '2018/高雄市市長.pdf（第1頁，候選人1號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/7ec2d4d3-7807-4798-a2aa-9a5a3eb5033d.pdf'),
  (13, 2022, 'taipei', '蔣萬安', '中國國民黨', '以包容、互助、共享、共生打造後疫情新首都。', '2022/臺北市市長.pdf（第1頁，候選人6號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/f420bdd8-9a89-458f-acc0-2370574270e0.pdf'),
  (14, 2022, 'new-taipei', '侯友宜', '中國國民黨', '新北市做大市、做大事，以安居樂業打造宜居城市。', '2022/新北市市長.pdf（第1頁，候選人2號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/f420bdd8-9a89-458f-acc0-2370574270e0.pdf'),
  (15, 2022, 'taoyuan', '張善政', '中國國民黨', '把握桃園轉骨升級期，打造幸福宜居家園、智慧科技新都與青年安家立業基地。', '2022/桃園市市長.pdf（第1頁，候選人1號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/f420bdd8-9a89-458f-acc0-2370574270e0.pdf'),
  (16, 2022, 'taichung', '盧秀燕', '中國國民黨', '以生活首都、永續城市為目標推動十大建設。', '2022/臺中市市長.pdf（第1頁，候選人3號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/f420bdd8-9a89-458f-acc0-2370574270e0.pdf'),
  (17, 2022, 'tainan', '黃偉哲', '民主進步黨', '以穩健務實推動永續、全齡、文化、便捷與富饒臺南。', '2022/台南市市長.pdf（第1頁，候選人5號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/f420bdd8-9a89-458f-acc0-2370574270e0.pdf'),
  (18, 2022, 'kaohsiung', '陳其邁', '民主進步黨', '延續兩年拚四年，再拚四年，讓高雄起飛。', '2022/高雄市市長.pdf（第1頁，候選人4號政見欄）；當選人核對：https://web.cec.gov.tw/api/file/f420bdd8-9a89-458f-acc0-2370574270e0.pdf');
