INSERT INTO promises (id, category_id, title, detail, source_reference, sort_order) VALUES
  (1, 1, '公開', '消滅特權，公部門資訊充分揭露，公共資源全民共享。', '2014/01臺北市市長.pdf（第1頁，候選人7號柯文哲政見欄）', 1),
  (2, 1, '透明', '打破黑箱，市政決策及預算執行接受全民監督。', '2014/01臺北市市長.pdf（第1頁，候選人7號柯文哲政見欄）', 2),
  (3, 1, '開放', '革除壟斷，創造優質自由競爭環境並提升服務品質。', '2014/01臺北市市長.pdf（第1頁，候選人7號柯文哲政見欄）', 3),
  (4, 1, '無私', '不分藍綠，政策由市民作主，從需求與最大公益出發。', '2014/01臺北市市長.pdf（第1頁，候選人7號柯文哲政見欄）', 4),
  (5, 1, '多元', '價值中立，保障基本人權並避免獨斷。', '2014/01臺北市市長.pdf（第1頁，候選人7號柯文哲政見欄）', 5),
  (6, 2, '參與', '成立市民投入市政議題的平台，保障公民提案權。', '2014/01臺北市市長.pdf（第1頁，候選人7號柯文哲政見欄）', 1),
  (7, 2, '對話', '持續與市民對話、共創利益，打造宜居進步城市。', '2014/01臺北市市長.pdf（第1頁，候選人7號柯文哲政見欄）', 2),
  (8, 2, '合作', '凝聚共識、落實分配正義，善用公民力量促進社會流動。', '2014/01臺北市市長.pdf（第1頁，候選人7號柯文哲政見欄）', 3),
  (9, 2, '分享', '關懷弱勢、縮短貧富差距，改善區域經濟與文化落差。', '2014/01臺北市市長.pdf（第1頁，候選人7號柯文哲政見欄）', 4),
  (10, 2, '包容', '尊重文化並面對歷史、族群與新移民議題，建立城市認同。', '2014/01臺北市市長.pdf（第1頁，候選人7號柯文哲政見欄）', 5),
  (11, 3, '四個在地', '推動在地就學、在地就養、在地就業與在地樂活。', '2014/02新北市市長.pdf（第1頁，候選人2號朱立倫政見欄）', 1),
  (12, 4, '捷運三環三線', '推進捷運三環三線，改善區域交通連結。', '2014/02新北市市長.pdf（第1頁，候選人2號朱立倫政見欄）', 1),
  (13, 5, '國民運動中心', '持續興建國民運動中心。', '2014/02新北市市長.pdf（第1頁，候選人2號朱立倫政見欄）', 1),
  (14, 6, '公共托育中心', '增設0至2歲公共托育中心。', '2014/02新北市市長.pdf（第1頁，候選人2號朱立倫政見欄）', 1),
  (15, 7, '安心營養午餐', '營養午餐提供有機安心蔬菜，支持在地有機農業。', '2014/02新北市市長.pdf（第1頁，候選人2號朱立倫政見欄）', 1),
  (16, 8, '老人共餐與公共托老', '結合老人共餐與閒置空間設置公共托老中心。', '2014/02新北市市長.pdf（第1頁，候選人2號朱立倫政見欄）', 1),
  (17, 9, '幸福保衛站', '結合便利商店提供急難兒童即時餐食與救助。', '2014/02新北市市長.pdf（第1頁，候選人2號朱立倫政見欄）', 1),
  (18, 10, '簡易都更', '簡化流程，協助欠缺市場誘因的老舊社區改善。', '2014/02新北市市長.pdf（第1頁，候選人2號朱立倫政見欄）', 1),
  (19, 11, '民主參與', '導入公民聽證、利益共享並杜絕炒地。', '2014/03桃園市市長.pdf（第1頁，候選人1號鄭文燦政見欄）', 1),
  (20, 12, '軌道與公車', '建構北北桃一小時生活圈，推動多條捷運延伸、桃林鐵路捷運化及公車8公里免費。', '2014/03桃園市市長.pdf（第1頁，候選人1號鄭文燦政見欄）', 1),
  (21, 13, '家庭支持', '興辦公托與公幼、培育保母；興建只租不售社宅並補貼在地就業青年房租。', '2014/03桃園市市長.pdf（第1頁，候選人1號鄭文燦政見欄）', 1),
  (22, 14, '生育健康', '提供育兒津貼、生育補助，推動幼兒與長者健保補助及國小免費營養早餐。', '2014/03桃園市市長.pdf（第1頁，候選人1號鄭文燦政見欄）', 1),
  (23, 15, '專責與永續', '成立青年事務局；加速污水接管，保育藻礁、河岸與埤塘。', '2014/03桃園市市長.pdf（第1頁，候選人1號鄭文燦政見欄）', 1),
  (24, 16, '博物館與再生', '規劃地方特色博物館，保存多元文化，推動公辦都更、舊商圈及農村再生。', '2014/03桃園市市長.pdf（第1頁，候選人1號鄭文燦政見欄）', 1),
  (25, 17, '整體計畫與大臺中123', '推動大臺中整體都市計畫、一條山手線、兩個國際港、三大副都心，並強化區公所。', '2014/04臺中市市長.pdf（第1至2頁，候選人2號林佳龍政見欄）', 1),
  (26, 18, '中區再生', '推動舊市區更新與再開發。', '2014/04臺中市市長.pdf（第1至2頁，候選人2號林佳龍政見欄）', 1),
  (27, 19, '捷運與路網', '推動捷運藍線、綠線延伸、環狀公路、偏遠公車、自行車及路平。', '2014/04臺中市市長.pdf（第1至2頁，候選人2號林佳龍政見欄）', 1),
  (28, 20, '安全城市', '補足警力設備、提升見警率；推動均優十二年國教、安全校園與終身學習。', '2014/04臺中市市長.pdf（第1至2頁，候選人2號林佳龍政見欄）', 1),
  (29, 21, '全齡支持', '托育補助延伸至3歲、增設公辦幼兒園；推動長者假牙與長照，興建青年勞工社宅。', '2014/04臺中市市長.pdf（第1至2頁，候選人2號林佳龍政見欄）', 1),
  (30, 22, '三種銀行與農業基金', '推動志工、食物、青創銀行，設置農業發展基金並支持青年農業。', '2014/04臺中市市長.pdf（第1至2頁，候選人2號林佳龍政見欄）', 1),
  (31, 23, '文化資產與水綠', '保存文化資產、支持藝文創作；推動河川、公園、污水接管、防淹水、空污治理與花博。', '2014/04臺中市市長.pdf（第1至2頁，候選人2號林佳龍政見欄）', 1),
  (32, 24, '文化立市與低碳', '興建文化設施、保存古蹟老屋，推動太陽能、公共自行車與低碳措施。', '2014/05臺南市市長.pdf（第1頁，候選人1號賴清德政見欄）', 1),
  (33, 25, '產業與七大安全', '發展港區、會展與新興產業；強化治安、道安、勞安、工安、校安、食安與環安。', '2014/05臺南市市長.pdf（第1頁，候選人1號賴清德政見欄）', 1),
  (34, 26, '治水與新農人', '整合治水、淨水、親水；支持新農人、有機農業、養殖專區與國際行銷。', '2014/05臺南市市長.pdf（第1頁，候選人1號賴清德政見欄）', 1),
