  (121, 92, '活力臺南、全齡照顧', '推動性別與多元共融、體育、三語學習、育兒托育、共融公園、長照與市立醫院。', '2022/台南市市長.pdf（第1頁，候選人5號黃偉哲政見欄）', 2),
  (122, 92, '文化臺南、國際聚焦', '迎接臺南400年，保存歷史場域、傳承藝術、打造觀光地標、大運河與歷史街區。', '2022/台南市市長.pdf（第1頁，候選人5號黃偉哲政見欄）', 3),
  (123, 92, '便捷臺南、區域均衡', '完善道路公車、鐵路立體化與捷運，改善防汛、農路水路與區域生活機能。', '2022/台南市市長.pdf（第1頁，候選人5號黃偉哲政見欄）', 4),
  (124, 92, '富饒臺南、壯大臺灣', '推進工業區、南科與沙崙，發展資安、醫療、半導體，升級農漁物流並支持就業居住。', '2022/台南市市長.pdf（第1頁，候選人5號黃偉哲政見欄）', 5),
  (125, 93, '科技與傳產轉型', '吸引國際研發進駐五大園區，推動傳統產業數位、淨零與高階製造。', '2022/高雄市市長.pdf（第1頁，候選人4號陳其邁政見欄）', 1),
  (126, 94, '就業與創業', '培力多元職涯、擴大產學合作與求職平台，提供文創、農創、青創、新創資源。', '2022/高雄市市長.pdf（第1頁，候選人4號陳其邁政見欄）', 1),
  (127, 95, '藝文與2050淨零', '扶植文化聚落與原創IP，促進國際展演；以產業、能源、生活、社會轉型改善空污。', '2022/高雄市市長.pdf（第1頁，候選人4號陳其邁政見欄）', 1),
  (128, 96, '捷運與聯外道路', '推動輕軌成圓、捷運延伸及黃線，建設國道、交流道、快速道路與園區聯外路。', '2022/高雄市市長.pdf（第1頁，候選人4號陳其邁政見欄）', 1),
  (129, 97, '社宅與教育品質', '推動社宅租補、雙語母語、數位能力並縮短城鄉差距。', '2022/高雄市市長.pdf（第1頁，候選人4號陳其邁政見欄）', 1),
  (130, 98, '長照幼托與全齡設施', '廣設公共托育、社區關懷與日照，興建運動中心、特色公園與無障礙設施。', '2022/高雄市市長.pdf（第1頁，候選人4號陳其邁政見欄）', 1),
  (131, 99, '高高平與防災', '以智慧科技改善區域基礎建設，增加消防、強化公安、都更危老與治水。', '2022/高雄市市長.pdf（第1頁，候選人4號陳其邁政見欄）', 1),
  (132, 100, '商圈夜市與國際市場', '以山海河港推動觀光會展，擴大農漁保險、智慧生產與多元通路。', '2022/高雄市市長.pdf（第1頁，候選人4號陳其邁政見欄）', 1),
  (133, 101, '性平與族群文化', '落實性別友善，改善月經貧窮；加強原鄉並保存原住民、客家、眷村及新住民文化。', '2022/高雄市市長.pdf（第1頁，候選人4號陳其邁政見欄）', 1),
